Below is a simple implementation of AES encryption and decryption in JavaScript. This script uses the AES algorithm in CBC mode with a 256-bit key.

**Encryption and Decryption Script**
--------------------------------

```javascript
// Import required libraries
const crypto = require('crypto');

// Define a function to generate a random key
function generateKey() {
    return crypto.randomBytes(32).toString('hex');
}

// Define a function to encrypt data
function encrypt(data, key) {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key, 'hex'), iv);
    let encrypted = cipher.update(data, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    return iv.toString('hex') + ':' + encrypted;
}

// Define a function to decrypt data
function decrypt(data, key) {
    const parts = data.split(':');
    const iv = Buffer.from(parts.shift(), 'hex');
    const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(key, 'hex'), iv);
    let decrypted = decipher.update(parts.join(':'), 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    return decrypted;
}

// Example usage:
const key = generateKey();
const data = 'Hello, World!';
const encryptedData = encrypt(data, key);
const decryptedData = decrypt(encryptedData, key);

console.log('Key:', key);
console.log('Original Data:', data);
console.log('Encrypted Data:', encryptedData);
